import json,importlib.util,subprocess,re
from pathlib import Path
from datetime import datetime,timezone
import requests
RUN=Path(__file__).resolve().parents[2];OUT=RUN/'analysis/monitoring';REPO=RUN.parents[1]
def read(p):return json.loads(p.read_text())
def save(p,x):p.write_text(json.dumps(x,indent=2)+'\n')
manifest=read(RUN/'manifest.json');evaluation=read(RUN/'analysis/autoscaling_evaluation.json')
assert manifest['status'] in ['succeeded','failed']
spec=importlib.util.spec_from_file_location('report_mooncake',REPO/'tools/report_mooncake.py');report=importlib.util.module_from_spec(spec);spec.loader.exec_module(report)
logpath=REPO/'findings-h100/mooncake-decay-16-400s/run.log'
plot=read(RUN/'analysis/plot_data.json');t0=plot['time_origin']['profiling_start_ns']
ids=report.replica_ids(logpath,'ttft-benchmark');ops,_,_=report.operation_data(RUN,ids,t0);pool,_=report.pool_data(RUN,t0)
root=read(OUT/'root_request_routing.json');routing=read(OUT/'all_conversation_routing.json');sessions=read(OUT/'session_tree_audit.json');credits=read(OUT/'request_credit_reconciliation.json');proxy=read(OUT/'proxy_error_correlation.json');concurrency=read(OUT/'concurrency_limit_events.json')
events=[json.loads(l) for l in (RUN/'deployment/events.jsonl').open()];teardown=[r for r in events if r.get('event')=='teardown_completed']
apps=requests.get('http://127.0.0.1:8265/api/serve/applications/',timeout=10).json().get('applications',{})
health=requests.get('http://10.1.154.0:9300/health',timeout=5).json()
gpu=subprocess.run(['nvidia-smi','--query-compute-apps=pid,used_gpu_memory','--format=csv,noheader'],capture_output=True,text=True,check=True).stdout.strip()
scale=evaluation.get('scale_events',[]);cost=evaluation.get('cost',{})
req=evaluation.get('slo_attainment',{}).get('steady',{}).get('requests',{})
textlog=re.sub(r'\x1b\[[0-9;]*m','',logpath.read_text())
source=read(OUT/'router_source_hash_audit.json')
credit_summary={'sent_credits':credits['sent_credits'],'exported_profiles':credits['completed_exported_records'],'exported_successes':credits['successful_exported_records'],'exported_errors':credits['failed_exported_records'],'unexported_cancelled_credits':credits['final_cancelled_credits'],'raw_was_cancelled_flags':credits['raw_record_cancelled_flags'],'grace_period_s':120,'note':'364 credits sent;362 exported profiles comprise350 successes and12 transport errors. Two remaining credits were cancelled after120s grace and a further10s cancellation-return timeout, without profile records. They are separate from the12 observed transport errors.'}
limits=['One repeat only; routing and arrival timing vary. These are replica GPU reservations on a fixed8-H100 node, not measured billing savings.','Original16-session linear-interpolated ramp and hold unchanged; no session down-ramp was configured.','No during-load producer removal should be claimed unless an actual during-load downscale appears. After-load removal alone does not prove a later request reused that producer cache.','Twelve observed ClientPayloadError streams coincide with proxy reload+120s clusters; retained old proxy stderr confirms forced connection closure. Per-socket tracing was not collected.','Two cancelled credits have no profile records; observed success/latency statistics exclude them.','Optional AIPerf GPU telemetry manager dropped after missed heartbeats; GPU-utilization export may be incomplete. Replica reservation telemetry remains available.','Mooncake operation histogram sums are approximate: Ray maps >4s observations to8s. Direct vLLM interval logs show longer successful average transfers.','Session graph rows are observed request spans. Last observed request end does not establish natural session completion or exact recycled lane ownership.','Recompute-on-load-failure policy is configured, but zero observed GET failures does not exercise that fallback.']
out={'title':'H100s, 16 sessions, Mooncake shared KV with 10k/sec decay and 400s scale down','run':RUN.name,'status':manifest['status'],'verified_at':datetime.now(timezone.utc).isoformat(),'teardown_completed':teardown[-1]['timestamp'] if teardown else None,'serve_applications_after_teardown':list(apps),'gpu_compute_processes_after_teardown':gpu,'mooncake_store_health_after_teardown':health,'requests':req,'credit_reconciliation':credit_summary,'telemetry_warning':'Optional AIPerf gpu_telemetry_manager dropped at16:31:52.121UTC after missed heartbeats; GPU-utilization export may be incomplete.','load_cost':cost.get('load'),'mean_allocated_gpus_during_load':cost.get('load',{}).get('gpu_hours',0)*3600/1050,'whole_run_cost':cost.get('experiment',cost.get('whole_run',cost.get('total'))),'scale_events':scale,'upscale_decisions':sum(e['direction']=='up' for e in scale),'downscale_decisions':sum(e['direction']=='down' for e in scale),'cache_operations':ops,'shared_pool':pool,'root_routing_summary':{'root_trees':root['root_sessions'],'root_requests':root['root_request_count'],'unmatched_root_requests':root['unmatched_root_requests'],'root_transitions_including_failures':len(root['all_root_replica_transitions']),'failed_receiving_root_transitions':sum(bool(r['profile_error']) for r in root['all_root_replica_transitions']),'all_conversation_transitions':len(routing['all_conversation_replica_transitions']),'failed_receiving_conversation_transitions':routing['failed_receiving_transition_count']},'session_audit_summary':{k:sessions.get(k) for k in ['root_tree_count','initial_source_lane_count','fresh_root_starts_beyond_initial','minimum_slot_reuse_events','source_trace_count','repeated_source_traces','was_cancelled_record_count','context_overflow_records_by_depth']},'concurrency_audit':{'observed_update_count':concurrency['observed_update_count'],'all_expected_limits_observed':concurrency['all_expected_limits_observed'],'expected_limits':list(range(1,17)),'no_down_ramp':True},'publisher_startup_failure_summary':read(OUT/'engine_startup_failure_summary.json'),'transport_error_summary':{'observed_errors':proxy['error_count'],'timing_consistent_with_reload_plus120s':proxy['timing_consistent_count'],'unattributed_errors':proxy['unattributed_count'],'direct_hardstop_worker_count':len(proxy['retained_direct_hardstop_stderr'])},'router_source_hashes_match':source['all_match'],'nonfatal_router_lifecycle_warning_count':textlog.count('await self._svc.free_reservation(request_id)'),'diagnostic_pipeline_status':read(RUN/'analysis/diagnostic_plots.json').get('status') if (RUN/'analysis/diagnostic_plots.json').exists() else None,'limits':limits,'known_limits':limits}
save(OUT/'run_outcome.json',out)
lines=[out['title'],f'Run: {RUN.name}',f'Status: {manifest["status"]}; teardown: {out["teardown_completed"]}',f'Requests: {json.dumps(req)}',f'Credit reconciliation: {json.dumps(credit_summary)}',f'Load GPU reservations: {json.dumps(out["load_cost"])}',f'Scaling: {json.dumps(scale)}',f'Cache operations: {json.dumps(ops)}',f'Pool: {json.dumps(pool)}',f'Routing: {json.dumps(out["root_routing_summary"])}',f'Transport: {json.dumps(out["transport_error_summary"])}','Known limits:',*limits]
(OUT/'run_outcome.txt').write_text('\n'.join(lines)+'\n')
print(json.dumps(out,indent=2))
